<?php declare(strict_types=1); ?>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?><?php if($success): ?><div class="settings-success"><?= kd_e($success) ?></div><?php endif; ?>
<div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Kampanya / kupon oluştur</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="campaign"><div class="customer-fields"><label>Kampanya adı<input name="name" required maxlength="150"></label><label>Kupon kodu<input name="code" required maxlength="60" placeholder="KASIM20"></label><label>İndirim türü<select name="discount_type"><option value="percentage">Yüzdelik</option><option value="fixed">Sabit tutar</option></select></label><label>İndirim değeri<input type="number" name="discount_value" min=".01" step=".01" required></label><label>Minimum sepet tutarı<input type="number" name="minimum_order" min="0" step=".01" value="0"></label><label>Maksimum indirim<input type="number" name="maximum_discount" min="0" step=".01" value="0"></label><label>Kullanım limiti (0=sınırsız)<input type="number" name="usage_limit" min="0" value="0"></label><label>Müşteri başı limit (0=sınırsız)<input type="number" name="per_customer_limit" min="0" value="0"></label><label>Başlangıç<input type="datetime-local" name="starts_at" value="<?= date('Y-m-d\TH:i') ?>"></label><label>Bitiş<input type="datetime-local" name="ends_at"></label><label class="field-wide">Açıklama<input name="description" maxlength="255"></label></div><button class="btn primary">Kampanyayı kaydet</button></form></section>
<section class="panel customer-form-panel"><h3>Hediye çeki oluştur</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="gift_card"><div class="customer-fields"><label>Tutar<input type="number" name="balance" min=".01" step=".01" required></label><label>Para birimi<select name="currency"><option>TRY</option><option>USD</option><option>EUR</option><option>GBP</option></select></label><label>Son kullanım tarihi<input type="date" name="expires_at"></label><label>Not<input name="notes"></label></div><button class="btn secondary">Hediye çeki oluştur</button></form></section></div>
<section class="panel customer-form-panel"><h3>Sadakat puanı düzenle</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="points"><div class="customer-fields"><label>Müşteri<select name="customer_id" required><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= kd_e($c['name']) ?> · <?= (int)$c['points_balance'] ?> puan</option><?php endforeach; ?></select></label><label>İşlem<select name="direction"><option value="earn">Puan ekle</option><option value="redeem">Puan düş</option></select></label><label>Puan<input type="number" name="points" min="1" max="1000000" required></label><label>Açıklama<input name="description"></label></div><button class="btn secondary">Puanı kaydet</button></form></section>
<section class="panel customer-list-panel"><div class="panel-head"><h3>Kampanyalar</h3><span class="result-count"><?= count($campaigns) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kampanya</th><th>Kod</th><th>İndirim</th><th>Kullanım</th><th>Tarih</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($campaigns as $c): ?><tr><td><?= kd_e($c['name']) ?></td><td><strong><?= kd_e($c['code']) ?></strong></td><td><?= $c['discount_type']==='percentage'?number_format((float)$c['discount_value'],2,',','.').' %':number_format((float)$c['discount_value'],2,',','.').' ₺' ?></td><td><?= (int)$c['usage_count'] ?> / <?= (int)$c['usage_limit']?:'∞' ?></td><td><?= kd_e(date('d.m.Y',strtotime($c['starts_at']))) ?> — <?= kd_e($c['ends_at']?date('d.m.Y',strtotime($c['ends_at'])):'—') ?></td><td><?= kd_e($c['status']) ?></td><td><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="campaign_status"><input type="hidden" name="campaign_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="status" value="<?= $c['status']==='active'?'inactive':'active' ?>"><button class="btn secondary"><?= $c['status']==='active'?'Durdur':'Etkinleştir' ?></button></form></td></tr><?php endforeach; ?><?php if(!$campaigns): ?><tr><td colspan="7">Kampanya bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section>
<div class="report-grid"><section class="panel customer-list-panel"><h3>Hediye çekleri</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Kod</th><th>Bakiye</th><th>Son kullanım</th><th>Durum</th></tr></thead><tbody><?php foreach($giftCards as $g): ?><tr><td><?= kd_e($g['code']) ?></td><td><?= number_format((float)$g['balance'],2,',','.') ?> <?= kd_e($g['currency']) ?></td><td><?= kd_e($g['expires_at']?:'—') ?></td><td><?= kd_e($g['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel customer-list-panel"><h3>Son sadakat hareketleri</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Müşteri</th><th>İşlem</th><th>Puan</th><th>Tarih</th></tr></thead><tbody><?php foreach($points as $p): ?><tr><td><?= kd_e($p['customer_name']) ?></td><td><?= kd_e($p['direction']) ?></td><td><?= (int)$p['points'] ?></td><td><?= kd_e(date('d.m.Y',strtotime($p['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
